4e (6/jour) — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Blessure-Critique.html&quot; title=&quot;Blessure critique&quot;&gt;blessure critique&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres-Iv.html&quot; title=&quot;Convocation de monstres IV&quot;&gt;convocation de monstres IV&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mur-De-Pierre.html&quot; title=&quot;Mur de pierre&quot;&gt;mur de pierre&lt;/a&gt;&lt;/i&gt; (DD 18), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Puissance-Divine.html&quot; title=&quot;Puissance divine&quot;&gt;puissance divine&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
