3e (7/jour) — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animation-Des-Morts.html&quot; title=&quot;Animation des morts&quot;&gt;animation des morts&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Blessure-Grave.html&quot; title=&quot;Blessure grave&quot;&gt;blessure grave&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;C&#233;cit&#233;surdit&#233;.html&quot; title=&quot;C&#233;cit&#233;/surdit&#233;&quot;&gt;C&#233;cit&#233;surdit&#233;&lt;/a&gt;&lt;/i&gt; (DD 17), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-De-La-Magie.html&quot; title=&quot;Dissipation de la magie&quot;&gt;dissipation de la magie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fusion-Dans-La-Pierre.html&quot; title=&quot;Fusion dans la pierre&quot;&gt;fusion dans la pierre&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
2e (7/jour) — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Appel-Des-Pierres.html&quot; title=&quot;Appel des pierres&quot;&gt;appel des pierres&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arme-Spirituelle.html&quot; title=&quot;Arme spirituelle&quot;&gt;arme spirituelle&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Blessure-Mod&#233;r&#233;e.html&quot; title=&quot;Blessure mod&#233;r&#233;e&quot;&gt;blessure mod&#233;r&#233;e&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Immobilisation-De-Personne.html&quot; title=&quot;Immobilisation de personne&quot;&gt;immobilisation de personne&lt;/a&gt;&lt;/i&gt; (DD 16), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Profanation.html&quot; title=&quot;Profanation&quot;&gt;profanation&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;n&#232;bres.html&quot; title=&quot;T&#233;n&#232;bres&quot;&gt;t&#233;n&#232;bres&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1er (7/jour) — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Blessure-L&#233;g&#232;re.html&quot; title=&quot;Blessure l&#233;g&#232;re&quot;&gt;blessure l&#233;g&#232;re&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-De-La-Foi.html&quot; title=&quot;Bouclier de la foi&quot;&gt;bouclier de la foi&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Entropique.html&quot; title=&quot;Bouclier entropique&quot;&gt;bouclier entropique&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brume-De-Dissimulation.html&quot; title=&quot;Brume de dissimulation&quot;&gt;brume de dissimulation&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Injonction.html&quot; title=&quot;Injonction&quot;&gt;injonction&lt;/a&gt;&lt;/i&gt; (DD 15), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ordre-Lib&#233;rateur.html&quot; title=&quot;Ordre lib&#233;rateur&quot;&gt;ordre lib&#233;rateur&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pierre-Magique.html&quot; title=&quot;Pierre magique&quot;&gt;pierre magique&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
0 (&#224; volont&#233;) — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Assistance-Divine.html&quot; title=&quot;Assistance divine&quot;&gt;assistance divine&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Deau.html&quot; title=&quot;Cr&#233;ation d&amp;#39;eau&quot;&gt;cr&#233;ation d’eau&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tincelle-(Mot-De-Pouvoir).html&quot; title=&quot;&#201;tincelle&quot;&gt;&#233;tincelle&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Poison.html&quot; title=&quot;D&#233;tection du poison&quot;&gt;d&#233;tection du poison&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lecture-De-La-Magie.html&quot; title=&quot;Lecture de la magie&quot;&gt;lecture de la magie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;paration.html&quot; title=&quot;R&#233;paration&quot;&gt;r&#233;paration&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-(Capacit&#233;).html&quot; title=&quot;r&#233;sistance&quot;&gt;r&#233;sistance&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Saignement.html&quot; title=&quot;Saignement&quot;&gt;saignement&lt;/a&gt;&lt;/i&gt; (DD 14)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Myst&#232;re&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Pierres.html&quot; title=&quot;Myst&#232;re des pierres&quot;&gt;pierre&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Avant le combat.&lt;/b&gt; L’antique fossoyeur se pr&#233;pare &#224; combattre en avalant ses &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Potions-Magiques.html&quot; title=&quot;Les potions magiques&quot;&gt;potions&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Morsure-Magique-Supr&#234;me.html&quot; title=&quot;Morsure magique supr&#234;me&quot;&gt;morsure magique supr&#234;me&lt;/a&gt;&lt;/i&gt; et d’&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Mage.html&quot; title=&quot;Armure de mage&quot;&gt;armure de mage&lt;/a&gt;&lt;/i&gt;. Avant d’attaquer, il utilise la &lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Pierres.html&quot; title=&quot;Myst&#232;re des pierres&quot;&gt;nage dans la terre&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Pierres.html&quot; title=&quot;Myst&#232;re des pierres&quot;&gt;vision cristalline&lt;/a&gt; pour observer ses ennemis tandis qu’ils combattent ses sous-fifres.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pendant le combat.&lt;/b&gt; L’antique fossoyeur se bat de pr&#233;f&#233;rence &#224; distance, &#224; l’aide de cr&#233;atures convoqu&#233;es, de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Colonne-De-Feu.html&quot; title=&quot;Colonne de feu&quot;&gt;colonne de feu&lt;/a&gt;&lt;/i&gt; et d’&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arme-Spirituelle.html&quot; title=&quot;Arme spirituelle&quot;&gt;arme spirituelle&lt;/a&gt;&lt;/i&gt;, afin d’infliger des d&#233;g&#226;ts de loin tandis qu’il utilise la &lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Pierres.html&quot; title=&quot;Myst&#232;re des pierres&quot;&gt;nage dans la terre&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Myst&#232;re-Des-Pierres.html&quot; title=&quot;Myst&#232;re des pierres&quot;&gt;vision cristalline&lt;/a&gt; pour se mettre &#224; l’abri. S’il est contraint de se battre au corps &#224; corps, il se montre particuli&#232;rement vicieux.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Statistiques de base.&lt;/b&gt; Voici les statistiques du fossoyeur sans &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Morsure-Magique-Supr&#234;me.html&quot; title=&quot;Morsure magique supr&#234;me&quot;&gt;morsure magique supr&#234;me&lt;/a&gt;&lt;/i&gt; ni &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Mage.html&quot; title=&quot;Armure de mage&quot;&gt;armure de mage&lt;/a&gt;&lt;/i&gt; : &lt;b&gt;CA&lt;/b&gt; 18, contact 15, pris au d&#233;pourvu 14 ; &lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +13 (1d6+5 plus &lt;a class=&quot;pagelink&quot; href=&quot;Goule.html#FIEVREDESGOULES&quot; title=&quot;Goule&quot;&gt;maladie&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Paralysie-(Capacit&#233;).html&quot; title=&quot;paralysie&quot;&gt;paralysie&lt;/a&gt;) et 2 &lt;i&gt;griffes de froid&lt;/i&gt;, +14 (1d6+5 plus 1d6 froid plus &lt;a class=&quot;pagelink&quot; href=&quot;Goule.html#FIEVREDESGOULES&quot; title=&quot;Goule&quot;&gt;maladie&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Paralysie-(Capacit&#233;).html&quot; title=&quot;paralysie&quot;&gt;paralysie&lt;/a&gt;).
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 20, &lt;b&gt;Dex&lt;/b&gt; 18, &lt;b&gt;Con&lt;/b&gt; -, &lt;b&gt;Int&lt;/b&gt; 15, &lt;b&gt;Sag&lt;/b&gt; 14, &lt;b&gt;Cha&lt;/b&gt; 18
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +8, &lt;b&gt;BMO&lt;/b&gt; +13 (+17 pour le croc-en-jambe), &lt;b&gt;DMD&lt;/b&gt; 27 (31 contre la bousculade, 33 contre le croc-en-jambe)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (griffe), &lt;a class=&quot;pagelink&quot; href=&quot;Arme-En-Main.html&quot; title=&quot;Arme en main&quot;&gt;Arme en main&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Naturelle-Sup&#233;rieure.html&quot; title=&quot;Armure naturelle sup&#233;rieure&quot;&gt;Armure naturelle sup&#233;rieure&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-R&#233;flexes.html&quot; title=&quot;Attaques r&#233;flexes&quot;&gt;Attaques r&#233;flexes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Croc-En-Jambe-Sup&#233;rieur.html&quot; title=&quot;Croc-en-jambe sup&#233;rieur&quot;&gt;Croc-en-jambe sup&#233;rieur&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Rage-Suppl&#233;mentaire.html&quot; title=&quot;Rage suppl&#233;mentaire&quot;&gt;Rage suppl&#233;mentaire&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Croc-En-Jambe.html&quot; title=&quot;Science du croc-en-jambe&quot;&gt;Science du croc-en-jambe&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; +17, &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; +16, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; +19, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +18, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +19, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +17
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; aklo, commun, commun des profondeurs, draconique, terreux ; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Don-Des-Langues.html&quot; title=&quot;Don des langues&quot;&gt;don des langues&lt;/a&gt;&lt;/i&gt; (pour comprendre seulement)
